191	// TestQueryEmptyHistoryStaysEmpty 专门锁定：尚无任何记录时取得的空历史，
192	// 在后续付款、退款发生后仍必须为空；新记录只能出现在新查询里。
193	func TestQueryEmptyHistoryStaysEmpty(t *testing.T) {
194		path := newTestLedger(t, []BalanceInit{
195			{Account: "aa", Asset: "usdc", Balance: 100},
196			{Account: "bb", Asset: "usdc", Balance: 100},
197		})
198		l := openOrFail(t, path)
199	
200		empty := mustQuery(t, l)
201		if len(empty.Settlements) != 0 || len(empty.Refunds) != 0 {
202			t.Fatalf("initial history must be empty: %+v", empty)
203		}
204		emptyBal := append([]BalanceView(nil), empty.Balances...)
205	
206		// 账本在另一个账户上发生完整的付款 → 退款。
207		if r := mustSettle(t, l, 100, intent("p1", "bb", "usdc", 50)); r.Status != StatusSettled {
208			t.Fatalf("p1: %+v", r) // charged 51（50+1），bb 余 49
209		}
210		if r := mustRefundOne(t, l, "r1", "p1", "oops"); r.Status != StatusRefundSuccess {
211			t.Fatalf("r1: %+v", r) // bb 回到 100
212		}
213	
214		// 旧空快照仍为空，且余额仍是当时内容（aa 100、bb 100）。
215		if len(empty.Settlements) != 0 || len(empty.Refunds) != 0 {
216			t.Fatalf("old snapshot history must stay empty: settlements=%d refunds=%d",
217				len(empty.Settlements), len(empty.Refunds))
218		}
219		if !reflect.DeepEqual(empty.Balances, emptyBal) {
220			t.Fatalf("old snapshot balances changed: %#v", empty.Balances)
221		}
222	
223		// 新查询包含新记录，且不影响旧快照的空列表。
224		fresh := mustQuery(t, l)
225		if len(fresh.Settlements) != 1 || fresh.Settlements[0].ID != "p1" {
226			t.Fatalf("new query must carry the payment: %+v", fresh.Settlements)
227		}
228		if len(fresh.Refunds) != 1 || fresh.Refunds[0].SettlementID != "p1" {
229			t.Fatalf("new query must carry the refund: %+v", fresh.Refunds)
230		}
231		if len(empty.Settlements) != 0 || len(empty.Refunds) != 0 {
232			t.Fatalf("taking a new query must not populate the old snapshot")
233		}
234	}
