254			t.Fatalf("p2: %+v", r) // aa 余 3000
255		}
256		if r := mustSettle(t, l, 50, intent("p3", "bb", "usdc", 400)); r.Status != StatusSettled {
257			t.Fatalf("p3: %+v", r) // fee=2, charged 402，bb 余 598
258		}
259	
260		wantFrozen := &Snapshot{
261			Balances: []BalanceView{
262				{Account: "aa", Asset: "usdc", Balance: 3000},
263				{Account: "bb", Asset: "usdc", Balance: 598},
264			},
265			Settlements: []Record{
266				{ID: "p1", Account: "aa", Paymaster: "pm", Asset: "usdc",
267					Amount: 1000, Nonce: 1, FeeBps: 100, Fee: 10, Charged: 1010, Seq: 1},
268				{ID: "p2", Account: "aa", Paymaster: "pm", Asset: "usdc",
269					Amount: 2000, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 2000, Seq: 2},
270				{ID: "p3", Account: "bb", Paymaster: "pm", Asset: "usdc",
271					Amount: 400, Nonce: 1, FeeBps: 50, Fee: 2, Charged: 402, Seq: 3},
272			},
273			Refunds: []RefundRecord{{
274				ID: "r1", SettlementID: "p1", Reason: "bad charge",
275				Account: "aa", Asset: "usdc", Amount: 1000, Fee: 10, Charged: 1010,
276				AfterSeq: 1, Seq: 1,
277			}},
278		}
279	
280		// 两份独立取得的结果初始一致。
281		snapA := mustQuery(t, l)
282		snapB := mustQuery(t, l)
283		assertSnap(t, snapA, wantFrozen, "snapA before edits")
284		assertSnap(t, snapB, wantFrozen, "snapB before edits")
285	
286		// 像调用者为自己展示所做的那样，任意改写 snapA：余额、结算、退款、追加与重排。
287		snapA.Balances[0].Account = "zz"
288		snapA.Balances[0].Asset = "btc"
289		snapA.Balances[0].Balance = 999_999
290		snapA.Balances = append(snapA.Balances, BalanceView{Account: "fake", Asset: "fake", Balance: 1})
291		snapA.Settlements[0].ID = "HACK"
292		snapA.Settlements[0].Account = "zz"
293		snapA.Settlements[0].Paymaster = "fake-pm"
294		snapA.Settlements[0].Asset = "btc"
295		snapA.Settlements[0].Amount = 1
296		snapA.Settlements[0].Nonce = 4242
297		snapA.Settlements[0].FeeBps = 9999
298		snapA.Settlements[0].Fee = 9
299		snapA.Settlements[0].Charged = 99
300		snapA.Settlements[0].Seq = 77
301		snapA.Settlements[1], snapA.Settlements[2] = snapA.Settlements[2], snapA.Settlements[1]
302		snapA.Settlements = append(snapA.Settlements, Record{ID: "fake-pay"})
303		snapA.Refunds[0].ID = "HACK-REF"
304		snapA.Refunds[0].SettlementID = "p2"
305		snapA.Refunds[0].Reason = "forged"
306		snapA.Refunds[0].Account = "zz"
307		snapA.Refunds[0].Asset = "btc"
308		snapA.Refunds[0].Amount = 1
309		snapA.Refunds[0].Fee = 1
310		snapA.Refunds[0].Charged = 2
311		snapA.Refunds[0].AfterSeq = 99
312		snapA.Refunds[0].Seq = 99
313		snapA.Refunds = append(snapA.Refunds, RefundRecord{ID: "fake-ref"})
314	
315		// 此前独立取得的另一份结果不能被改写波及（余额与历史一起受保护）。
316		assertSnap(t, snapB, wantFrozen, "snapB after editing snapA")
317	
318		// 再次查询仍得到真实业务产生的数据：原编号、账户、资产、金额、手续费、
319		// 成功序号，以及退款原因和关联原付款全部完整。
320		snapC := mustQuery(t, l)
321		assertSnap(t, snapC, wantFrozen, "ledger after editing snapA")
322		rp1 := snapC.Settlements[0]
323		if rp1.ID != "p1" || rp1.Account != "aa" || rp1.Asset != "usdc" ||
324			rp1.Amount != 1000 || rp1.Fee != 10 || rp1.FeeBps != 100 || rp1.Seq != 1 {
325			t.Fatalf("real p1 record lost after caller edit: %+v", rp1)
326		}
327		rr1 := snapC.Refunds[0]
328		if rr1.ID != "r1" || rr1.Reason != "bad charge" || rr1.SettlementID != "p1" ||
