330			rr1.Fee != 10 || rr1.Charged != 1010 || rr1.Seq != 1 {
331			t.Fatalf("real r1 record lost after caller edit: %+v", rr1)
332		}
333	
334		// 对返回数据的改动不能改变业务判定：
335		// 已退款的原付款按原请求再提交，仍返回 duplicate 和原结算记录，不再次扣款。
336		dup := mustSettle(t, l, 100, intent("p1", "aa", "usdc", 1000))
337		if dup.Status != StatusDuplicate || dup.Record == nil ||
338			dup.Record.Seq != 1 || dup.Record.Charged != 1010 {
339			t.Fatalf("refunded payment retry want duplicate with original record: %+v", dup)
340		}
341		if bal, _ := l.Balance("aa", "usdc"); bal != 3000 {
342			t.Fatalf("duplicate after snapshot edit charged again: bal=%d", bal)
343		}
344	
345		// 用新的退款编号申请退回同一付款：仍为 already_refunded，不增加余额。
346		rx := mustRefundOne(t, l, "rx", "p1", "trying again")
347		if rx.Status != StatusAlreadyRefunded {
348			t.Fatalf("want already_refunded, got %+v", rx)
349		}
350		if bal, _ := l.Balance("aa", "usdc"); bal != 3000 {
351			t.Fatalf("already_refunded after snapshot edit changed balance: %d", bal)
352		}
353	
354		// 后续付款仍按真实余额结算（篡改既没有抬高也没有压低可用余额）。
355		p4 := mustSettle(t, l, 0, intent("p4", "aa", "usdc", 3000))
356		if p4.Status != StatusSettled || p4.Record.Seq != 4 {
357			t.Fatalf("payment must settle against the real balance: %+v", p4)
358		}
359		final := mustQuery(t, l)
360		if final.Balances[0].Balance != 0 || final.Balances[1].Balance != 598 {
361			t.Fatalf("final balances: %+v", final.Balances)
362		}
363		if len(final.Settlements) != 4 || len(final.Refunds) != 1 {
364			t.Fatalf("final history counts: settlements=%d refunds=%d",
365				len(final.Settlements), len(final.Refunds))
366		}
367	}
